class Solution:
    def minStoneSum(self, piles: List[int], k: int) -> int:
        for i, x in enumerate(piles):
            piles[i] = -x
        heapq.heapify(piles)
        for i in range(k):
            heapq.heappush(piles, heapq.heappop(piles)//2)
        return -sum(piles)

class Solution:
    def minSwaps(self, s: str) -> int:
        res, bal = 0, 0
        for ch in s:
            bal += 1 if ch == '[' else -1
            if bal == -1:
                res += 1
                bal = 1
        return res

class Solution:
    def minSwaps(self, s: str) -> int:
        result = curr = 0
        for c in s:
            if c == ']':
                curr += 1
                result = max(result, curr)
            else:
                curr -= 1
        return (result+1)//2

